function Bibliotheque({ livres }) {
  const [recherche, setRecherche] = useState("");
  const visibles = livres.filter((livre) =>
    livre.titre.toLowerCase().includes(recherche.toLowerCase())
  );
  return <><Champ value={recherche} onChange={setRecherche} />
    <Liste livres={visibles} /></>;
}
